    },
    {
      "indicator": "MM50",
      "reading": "14.4292",
      "interpretation": "MM50 acima da MM200 → tendência de médio prazo sustentada; MM20 ligeiramente abaixo sinaliza menor força de curto prazo."
    },
    {
      "indicator": "MM200",
      "reading": "13.8199",
      "interpretation": "MM200 bem abaixo do preço → tendência de longo prazo é positiva; nível relevante de suporte estrutural."
    },
    {
      "indicator": "EMA9",
      "reading": "14.3588",
      "interpretation": "EMA9 ligeiramente abaixo da EMA21 enquanto o preço está acima de ambas → sinais mistos de curtíssimo prazo; possível pullback/continuação."
    },
    {
      "indicator": "EMA21",
